+    private static void execute(String... propertyFlags) throws Exception {
+        // Property flags are usually added as additionally options when running a jtreg test. To simulate that, we
+        // explicitly need to set the -Dtest.java.opts to propagate them to the Test VM. When we only specify the
+        // property flags in '@run main/othervm', they are not passed to the Test VM.
+        List<String> command = new ArrayList<>();
+        // Set jtreg set properties explicitly since we spawn a separate VM
+        command.add("-Dtest.class.path=" + Utils.TEST_CLASS_PATH);
+        command.add("-Dtest.jdk=" + Utils.TEST_JDK);
+
+        command.add("-Dtest.java.opts=" + String.join(" ", propertyFlags)); // Properties for Test VM
+        command.addAll(List.of(propertyFlags)); // Properties for Driver VM
+        command.add(TestDFlags.class.getName());
+        ProcessTools.executeTestJava(command).shouldHaveExitValue(0);
+    }
+
+    // Clean up the many replay files generated by using -DDumpReplay=true.
+    private static void deleteReplayFiles() {
+        Path scratchDir = Path.of(System.getProperty("user.dir"));
+
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(scratchDir, "replay_pid*_compid*.log")) {
+            for (Path file : files) {
+                Files.deleteIfExists(file);
+            }
+        } catch (IOException e) {
+            throw new RuntimeException("Could not delete replay files from " + scratchDir, e);
+        }
+    }
